begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email) values
 ('5a000000-0000-4000-8000-000000000001','authenticated','authenticated','push-owner@example.test'),
 ('5a000000-0000-4000-8000-000000000002','authenticated','authenticated','push-client@example.test'),
 ('5a000000-0000-4000-8000-000000000003','authenticated','authenticated','push-foreign@example.test');
insert into public.trainer_workspaces(id,owner_user_id,name,timezone) values ('6a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001','Synthetic push','Asia/Almaty');
insert into public.client_records(id,workspace_id,user_id,display_name) values ('7a000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000002','Synthetic client');
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_one]','ios','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),1);
select is(jsonb_array_length(public.own_push_devices()),1,'own registration metadata readable');
select ok(not (public.own_push_devices()->0 ? 'token'),'metadata never exposes token');
select throws_ok($$select * from private.push_devices$$,'42501',null,'raw tokens denied');
select throws_ok($$select * from private.push_deliveries$$,'42501',null,'delivery state denied');
select throws_ok($$select public.claim_push_v1(1)$$,'42501',null,'client cannot claim');
select throws_ok($$select public.schedule_push_v1(now(),'08:00')$$,'42501',null,'client cannot schedule');
select throws_ok($$select public.register_push_device('9a000000-0000-4000-8000-000000000001','invalid','ios','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),2)$$,'23514',null,'invalid token rejects without mutating old binding');
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000003","session_id":"8a000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(jsonb_array_length(public.own_push_devices()),0,'foreign metadata invisible');
select throws_ok($$select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_two]','android','aa000000-0000-4000-8000-000000000002',repeat('wrong-secret-',4),3)$$,'42501',null,'foreign cannot hijack device');
select public.reconcile_push_device('9a000000-0000-4000-8000-000000000001',repeat('wrong-secret-',4),4);
reset role;
select is((select count(*)::integer from private.push_devices),1,'foreign reconcile without device capability cannot revoke');
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_two]','ios','aa000000-0000-4000-8000-000000000002',repeat('synthetic-secret-',4),5);
select public.unregister_push_device('9a000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),6);
reset role;
select is((select count(*)::integer from private.push_devices),1,'stale generation logout cannot revoke rotated device');
set local role authenticated;
select public.unregister_push_device('9a000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000002',repeat('synthetic-secret-',4),7);
reset role;
select is((select count(*)::integer from private.push_devices),0,'logout revokes exact device');
set local role authenticated;
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_one]','ios','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),1);
reset role;
select is((select count(*)::integer from private.push_devices),0,'late registration cannot resurrect logged-out binding');
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000003","session_id":"8a000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_one]','android','aa000000-0000-4000-8000-000000000002',repeat('synthetic-secret-',4),8);
select is(jsonb_array_length(public.own_push_devices()),1,'same installation account switch binds only current caller');
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select public.reconcile_push_device('9a000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),9);
select is(jsonb_array_length(public.own_push_devices()),0,'startup with denied permission removes proven foreign binding');
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_two]','ios','aa000000-0000-4000-8000-000000000002',repeat('synthetic-secret-',4),10);
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.unregister_push_device('9a000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),11);
select is(jsonb_array_length(public.own_push_devices()),1,'old same-user session cannot revoke relogin generation');
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select public.unregister_push_device('9a000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000002',repeat('synthetic-secret-',4),12);


set local role anon;
select throws_ok($$select public.own_push_devices()$$,'42501',null,'anon cannot read metadata');
select throws_ok($$select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_one]','ios','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),8)$$,'42501',null,'anon cannot register');
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values ('ba000000-0000-4000-8000-000000000001','6a000000-0000-4000-8000-000000000001','7a000000-0000-4000-8000-000000000001','2099-10-04T05:00:00Z','2099-10-04T06:00:00Z','confirmed');
select is(public.schedule_push_v1('2099-10-04T02:59:00Z','08:00'),0,'Almaty 07:59 before reminder and morning');
select is(public.schedule_push_v1('2099-10-04T03:00:00Z','08:00'),2,'Almaty 08:00 reminder at two hours and daily summary');
select is(public.schedule_push_v1('2099-10-04T03:00:00Z','08:00'),0,'scheduler replay does not duplicate feed');
select is(public.schedule_push_v1('2099-10-04T04:00:00Z','08:00'),0,'late repeat does not duplicate');
select is(public.schedule_push_v1('2099-10-05T03:00:00Z','08:00'),0,'empty day does not emit summary');
update public.bookings set starts_at='2099-10-04T09:00:00Z',ends_at='2099-10-04T10:00:00Z' where id='ba000000-0000-4000-8000-000000000001';
select ok(not private.push_eligible((select id from public.notifications where kind='booking_reminder'),'2099-10-04T03:00:00Z'),'reschedule invalidates old reminder');
select is(public.schedule_push_v1('2099-10-04T07:00:00Z','08:00'),1,'new time creates exactly one new reminder');
update public.bookings set status='cancelled_by_trainer' where id='ba000000-0000-4000-8000-000000000001';
select is(public.schedule_push_v1('2099-10-04T08:00:00Z','08:00'),0,'cancelled booking not scheduled');
select ok(not private.push_eligible((select id from public.notifications where kind='daily_plan' limit 1),'2099-10-04T08:00:00Z'),'daily due job rechecks now-empty cancelled day');
select ok(not private.push_eligible((select id from public.notifications where kind='booking_reminder' order by created_at desc limit 1),'2099-10-04T08:00:00Z'),'cancelled reminder not deliverable');
update public.bookings set status='confirmed',starts_at='2099-10-05T00:00:00Z',ends_at='2099-10-05T01:00:00Z' where id='ba000000-0000-4000-8000-000000000001';
select is(public.schedule_push_v1('2099-10-04T22:00:00Z','08:00'),1,'Almaty next day 03:00 reminder crosses UTC date');
update public.trainer_workspaces set timezone='America/New_York' where id='6a000000-0000-4000-8000-000000000001';
update public.bookings set starts_at='2099-03-08T14:00:00Z',ends_at='2099-03-08T15:00:00Z' where id='ba000000-0000-4000-8000-000000000001';
select is(public.schedule_push_v1('2099-03-08T12:00:00Z','08:00'),2,'DST spring local morning and absolute two-hour reminder');
delete from public.notifications where kind in ('daily_plan','booking_reminder') and created_at='2099-03-08T12:00:00Z';
select is(public.schedule_push_v1('2099-03-08T13:00:00Z','08:00'),2,'late first run catches due reminder before start and current daily plan');
select is(public.schedule_push_v1('2099-03-08T14:00:00Z','08:00'),0,'at-start reminder is skipped');
update public.bookings set starts_at='2099-11-01T15:00:00Z',ends_at='2099-11-01T16:00:00Z' where id='ba000000-0000-4000-8000-000000000001';
select is(public.schedule_push_v1('2099-11-01T13:00:00Z','08:00'),2,'DST autumn local morning and absolute two-hour reminder');
select throws_ok($$select public.schedule_push_v1(now(),null)$$,'P0001','push_schedule_configuration_required','morning is explicit configuration');

select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000002","session_id":"8a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_one]','ios','aa000000-0000-4000-8000-000000000001',repeat('synthetic-secret-',4),13);
update private.push_devices set updated_at=clock_timestamp()-interval '1 hour';
insert into public.notifications(workspace_id,recipient_user_id,recipient_role,client_record_id,event_key,kind,target_type,target_id,payload) values ('6a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000002','client','7a000000-0000-4000-8000-000000000001','synthetic-delivery','booking_confirmed','booking','ba000000-0000-4000-8000-000000000001','{"version":1}');
select set_config('test.claim',public.claim_push_v1(100)::text,true);
select ok(jsonb_array_length(current_setting('test.claim')::jsonb)>0,'service claims events');
select is(jsonb_array_length(public.claim_push_v1(100)),0,'concurrent logical replay cannot reclaim active lease');
select set_config('test.delivery',(select x::text from jsonb_array_elements(current_setting('test.claim')::jsonb) x where x->>'notificationId'=(select id::text from public.notifications where event_key='synthetic-delivery')),true);
select ok(not public.complete_push_v1((current_setting('test.delivery')::jsonb->>'id')::uuid,gen_random_uuid(),'delivered'),'foreign lease cannot complete');
select ok(public.complete_push_v1((current_setting('test.delivery')::jsonb->>'id')::uuid,(current_setting('test.delivery')::jsonb->>'lease')::uuid,'ticket','synthetic-ticket'),'ticket persisted');
select ok(not public.complete_push_v1((current_setting('test.delivery')::jsonb->>'id')::uuid,(current_setting('test.delivery')::jsonb->>'lease')::uuid,'ticket','synthetic-ticket'),'completion replay cannot mutate again');
update private.push_deliveries set due_at=clock_timestamp()-interval '1 second' where id=(current_setting('test.delivery')::jsonb->>'id')::uuid;
select set_config('test.receipt',public.claim_push_v1(100)::text,true);
select is(current_setting('test.receipt')::jsonb->0->>'state','receipt','ticket lease requests receipt');
select public.register_push_device('9a000000-0000-4000-8000-000000000001','ExpoPushToken[synthetic_device_token_two]','ios','aa000000-0000-4000-8000-000000000003',repeat('synthetic-secret-',4),14);
select ok(public.complete_push_v1((current_setting('test.receipt')::jsonb->0->>'id')::uuid,(current_setting('test.receipt')::jsonb->0->>'lease')::uuid,'invalid',null,'DeviceNotRegistered'),'invalid receipt handled');
select is((select count(*)::integer from private.push_devices),1,'old invalid receipt cannot remove rotated generation');
insert into public.notifications(workspace_id,recipient_user_id,recipient_role,client_record_id,event_key,kind,target_type,target_id,payload) values ('6a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000002','client','7a000000-0000-4000-8000-000000000001','synthetic-current-delivery','booking_confirmed','booking','ba000000-0000-4000-8000-000000000001','{"version":1}');
select set_config('test.current_claim',public.claim_push_v1(100)::text,true);
select ok(public.complete_push_v1((current_setting('test.current_claim')::jsonb->0->>'id')::uuid,(current_setting('test.current_claim')::jsonb->0->>'lease')::uuid,'invalid',null,'DeviceNotRegistered'),'current generation invalid ticket handled');
select is((select count(*)::integer from private.push_devices),0,'current invalid device cleaned up');
update private.push_deliveries set lease_until=clock_timestamp()-interval '1 second' where state='sending';
select is(jsonb_array_length(public.claim_push_v1(100)),0,'expired sending claims are not resent');
select ok(exists(select 1 from private.push_deliveries where state='unknown'),'expired sending lease retains explicit unknown outcome');
select is((select count(*)::integer from private.push_deliveries where notification_id=(select id from public.notifications where event_key='synthetic-delivery')),1,'event replay preserves one logical delivery');
set local role authenticated;
select ok((public.open_push_notification('6a000000-0000-4000-8000-000000000001',(select id from public.notifications where event_key='synthetic-delivery'))->>'role')='client','own push routing role authorized');
reset role;
select set_config('request.jwt.claims','{"sub":"5a000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('test.target',(select id::text from public.notifications where event_key='synthetic-delivery'),true);
set local role authenticated;
select throws_ok(format('select public.open_push_notification(%L,%L)','6a000000-0000-4000-8000-000000000001',current_setting('test.target')),'P0002',null,'foreign push cannot resolve own object');
reset role;
select * from finish();
rollback;
